        data.putInt("maxPerks",77);data.putString("starterItem","minecraft:diamond");data.put("starterItemTag",new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND).save(new net.minecraft.nbt.CompoundTag()));
        configTab(1);var button=screen.children().stream().filter(w->w instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals(net.minecraft.network.chat.Component.translatable("config.zombierool.defaults").getString())).map(w->(net.minecraft.client.gui.components.Button)w).findFirst().orElseThrow();button.onPress();
