    private void physics(net.minecraft.server.level.ServerPlayer p){
        var level=p.serverLevel();
        for(int type=0;type<5;type++){
            net.minecraft.world.entity.Entity moon=switch(type){case 0->new me.cryo.zombierool.item.throwable.Grenade.GrenadeEntity(me.cryo.zombierool.core.registry.ZRThrowableRegistry.GRENADE_ENTITY.get(),level);case 1->new net.minecraft.world.entity.item.ItemEntity(level,0,0,0,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.STONE));case 2->new net.minecraft.world.entity.item.PrimedTnt(net.minecraft.world.entity.EntityType.TNT,level);case 3->new net.minecraft.world.entity.projectile.Arrow(net.minecraft.world.entity.EntityType.ARROW,level);default->new net.minecraft.world.entity.ExperienceOrb(level,0,0,0,1);};
            moon.setPos(70.5,75,.5);moon.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);moon.tick();double lunar=moon.getDeltaMovement().y;
            moon.setPos(30.5,75,.5);moon.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);moon.tick();double earth=moon.getDeltaMovement().y;
            check(earth<0&&Math.abs(lunar/earth-.167)<.002,"Spatial gravity and Earth restoration for projectile/item class "+type);moon.discard();
        }
        var mob=net.minecraft.world.entity.EntityType.HUSK.create(level);mob.setPos(70.5,75,.5);LunarPhysics.living(new net.minecraftforge.event.entity.living.LivingEvent.LivingTickEvent(mob));check(Math.abs(mob.getAttributeValue(net.minecraftforge.common.ForgeMod.ENTITY_GRAVITY.get())-.08*.167)<.0001,"Mob receives lunar gravity");mob.setPos(30.5,75,.5);LunarPhysics.living(new net.minecraftforge.event.entity.living.LivingEvent.LivingTickEvent(mob));check(Math.abs(mob.getAttributeValue(net.minecraftforge.common.ForgeMod.ENTITY_GRAVITY.get())-.08)<.0001,"Mob recovers Earth gravity");mob.discard();
        p.setOnGround(true);p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.knockback(.4,1,0);double lunarKick=p.getDeltaMovement().y;p.setPos(30.5,65,.5);p.setOnGround(true);p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.knockback(.4,1,0);double earthKick=p.getDeltaMovement().y;check(earthKick>0&&Math.abs(lunarKick/earthKick-Math.sqrt(.167))<.001,"Damage impulse scales with square root of local gravity");p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.setPos(70.5,65,.5);
    }
